// Loyalty is shown as five named levels; each level has one clear effect.
const LOY=[{nm:'hostile', c:'#c0473a',q:.2, d:'do harm and leave the building'},
           {nm:'unreliable', c:'#e0866a',q:.5, d:'do harm, leave the building in a crisis'},
           {nm:'wavering',c:'#c9a25a',q:.75,d:'work at half strength, no bonus'},
           {nm:'loyal',   c:'#9bb04a',q:1,  d:'work at full strength, bonus active'},
           {nm:'devoted',   c:'#7fd08a',q:1.2,d:'work best of all, bonus active'}];
const loyLvl=v=>v<=1?0:v<=3?1:v<=5?2:v<=7?3:4;
const QUORUM=150;
// weapons stay in stock when handed out: a fighter holds one, the rest are free
const freeGuns=S=>Math.max(0,Math.round(S.gun-S.mil));
// What a loyal faction gives every night just by staying in the building (needs loyalty 6+).
// With loyalty 3 or less the faction works against you (bad).
const FAC_BONUS={
  ros:{t:'the Congress\'s lawyers',            fx:{leg:1},            bad:{leg:-1}},
  kr: {t:'Moscow party cells',  fx:{ppl:60},           bad:{rad:1}},
  agr:{t:'ties with state farms',        fx:{sup:.3},           bad:{sup:-.2}},
  otc:{t:'reserve generals',          fx:{pts:{mo:2,gs:2}},  bad:{pts:{mo:-1,gs:-1}}},
  sm: {t:'young and telegenic',   fx:{med:2},            bad:{city:-1}},
  kol:{t:'Congress quorum',            fx:{leg:1},            bad:{leg:-1}},
  rne:{t:'discipline and guards at the entrances', fx:{hope:1,rad:1}, bad:{rad:2}},
  so: {t:'career officers',         fx:{hope:1,pts:{gs:1}},bad:{rad:1}},
};
const facBonus=(S,F)=>{const f=S.fac[F.id],B=FAC_BONUS[F.id]; return f.n<=0?null:f.loy>=6?{on:1,fx:B.fx,t:B.t}:f.loy<=3?{on:-1,fx:B.bad,t:B.t}:{on:0,fx:B.fx,t:B.t};};
