const outSt=(S,o)=>o.id==='ost'?(S.pts.ost>=100?'vs':'kr'):o.id==='radio'?(S.phase>=2&&!S.flags.noPower&&S.sup>0?'vs':'off'):(S.out&&S.out[o.id])||o.s;
