// the Kremlin drags one outlet a step towards itself; returns the line for the morning report
function kremlinPull(S){const c=OUTLETS.filter(o=>!outLocked(S,o)&&['vs','neu'].includes(outSt(S,o))); if(!c.length)return null;
  const o=c[Math.floor(Math.random()*c.length)], st=outSt(S,o); S.out[o.id]=st==='vs'?'neu':'kr';
  return st==='vs'?o.nm+': the editor was told what he is risking. The paper has fallen silent.':o.nm+': a soft loan, newsprint and broadcast frequencies. Now it backs the Kremlin.';}
